-- v17 yoga: a pose library and a weekly yoga plan.
-- Poses are catalog exercises of kind 'yoga', stored like the v13 stretches: bodyweight holds that never
-- enter strength plans or weekly set counts. A pose also carries what a how-to page needs beyond steps:
-- its Sanskrit name, where it sits in the library, what it works, how long to hold it and cautions.
-- Photos come from Wikimedia Commons under licenses that allow display with attribution, resized into
-- server/static/exercises; image_credits holds one author, license and file page per photo, in the
-- same order as images, because those licenses require the credit to be shown.
-- Cautions map the conditions NCCIH lists as reasons to modify poses (preexisting injuries, lumbar
-- spine disease, severe high blood pressure, glaucoma, balance issues, pregnancy) onto the poses that
-- load them; they are not pose-specific trial findings. Sources are listed in docs/design-v17-yoga.md.

ALTER TABLE exercises
    ADD COLUMN sanskrit      TEXT,
    ADD COLUMN pose_group    TEXT CHECK (pose_group IN ('standing', 'kneeling', 'seated', 'prone', 'supine')),
    ADD COLUMN effect        TEXT,
    ADD COLUMN hold_note     TEXT,
    ADD COLUMN cautions      TEXT[] NOT NULL DEFAULT '{}',
    ADD COLUMN image_credits JSONB  NOT NULL DEFAULT '[]';

ALTER TABLE exercises
    DROP CONSTRAINT exercises_kind_check,
    DROP CONSTRAINT exercises_stretch_shape,
    DROP CONSTRAINT exercises_per_side_stretch,
    ADD CONSTRAINT exercises_kind_check CHECK (kind IN ('strength', 'stretch', 'yoga')),
    ADD CONSTRAINT exercises_hold_shape CHECK (kind = 'strength' OR (measure = 'seconds' AND load = 'bodyweight' AND user_id IS NULL)),
    ADD CONSTRAINT exercises_per_side_hold CHECK (NOT per_side OR kind <> 'strength'),
    ADD CONSTRAINT exercises_pose_shape CHECK ((kind = 'yoga') = (pose_group IS NOT NULL)),
    ADD CONSTRAINT exercises_credits_sizes CHECK (jsonb_typeof(image_credits) = 'array' AND jsonb_array_length(image_credits) <= cardinality(images));

