-- A person's weekly yoga plan: how many days, which flow, and the weekdays chosen for them (1 is
-- Monday). level_since is when the current flow length started, so the progression offer counts
-- only weeks done at this length.
CREATE TABLE yoga_plans (
    user_id       BIGINT   PRIMARY KEY REFERENCES users (id) ON DELETE CASCADE,
    days_per_week SMALLINT NOT NULL CHECK (days_per_week BETWEEN 1 AND 7),
    flow_minutes  SMALLINT NOT NULL CHECK (flow_minutes IN (10, 20, 30)),
    weekdays      SMALLINT[] NOT NULL,
    level_since   DATE     NOT NULL,
    updated_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    CHECK (cardinality(weekdays) = days_per_week AND weekdays <@ ARRAY[1, 2, 3, 4, 5, 6, 7]::smallint[])
);
